Script.Workflow:
module touching_list;
using system::*;
namespace demo
{
  class TouchingListItem
  {
    prop Text: string = "" {not observe}
    prop Reveal: int = 0 {}
    prop Maximum: int = 0 {not observe}
    new (text: string) { Text = text; }
  }
}

Bounds.att.ExpectedBounds-bind:
{
              x1: -ViewModel.Reveal;
              y1: 0;
              x2: self.CachedBounds.x2 - self.CachedBounds.x1 - ViewModel.Reveal;
              y2: self.CachedBounds.y2 - self.CachedBounds.y1 - 1;
            }

Instance.ref.Members:
prop Items: observe TouchingListItem^[] = {} {const, not observe}
var serial: int = 0;
var swipeItem: TouchingListItem^ = null;
var multipleContacts: bool = false;

func ResetSwipe(): void
{
  if (swipeItem is not null) { swipeItem.Reveal = 0; }
  swipeItem = null;
}

func AddItems(): void
{
  for (i in range[0, 5))
  {
    serial = serial + 1;
    Items.Add(new TouchingListItem^("Item " & cast string serial
      & " — Lorem ipsum dolor sit amet, consectetur adipiscing elit. Swipe left to reveal DELETE IT; release at full reveal to remove this item."));
  }
}

func BeginSwipe(arguments: GuiPointSequenceStartedEventArgs*): void
{
  ResetSwipe();
  multipleContacts = false;
  var composition = arguments.compositionSource;
  while (composition is not null and composition != list.BoundsComposition)
  {
    if (var row: TouchingListItemTemplate* = composition as TouchingListItemTemplate*)
    {
      if (row.AssociatedListControl == list) { swipeItem = row.ViewModel; }
      break;
    }
    composition = composition.Parent;
  }
}

func EndSwipe(arguments: GuiPointSequenceEndedEventArgs*): void
{
  var target = swipeItem;
  var remove = false;
  if (target is not null and not multipleContacts and arguments.reason == PointSequenceEndReason::Succeeded)
  {
    remove = target.Maximum > 0 and target.Reveal == target.Maximum;
  }
  ResetSwipe();
  if (remove)
  {
    GuiApplication::GetApplication().InvokeInMainThread(list.RelatedControlHost, func(): void
    {
      if (Items.Contains(target)) { Items.Remove(target); }
    });
  }
}

att.BoundsComposition-set.ev.pointAction-eval:
{
                  if (arguments.eventType == GuiPointEventsType::Down and arguments.pointId != 0)
                  {
                    self.multipleContacts = true;
                    self.ResetSwipe();
                  }
                }

att.BoundsComposition-set.ev.pointGesture-eval:
{
                  if (not arguments.handled and arguments.Gesture is GuiPointGesture_Scrolling)
                  {
                    var scrolling = cast GuiPointGesture_Scrolling arguments.Gesture;
                    if (not scrolling.isVertical)
                    {
                      arguments.selected = true;
                      arguments.handled = true;
                      if (self.swipeItem is not null and not self.multipleContacts)
                      {
                        self.swipeItem.Reveal = Math::Max(0, Math::Min(self.swipeItem.Maximum, self.swipeItem.Reveal - scrolling.distance));
                      }
                    }
                  }
                }
